<script setup lang="ts">
import { requestSchema, type Personalization } from '@ellas/shared';

const selection=useSelection();const busy=ref(false);const uploadBusy=ref(false);const error=ref('');const fields=ref<Record<string,string>>({});const uploadedName=ref('');
const type=ref<'presupuesto'|'pedido'>('presupuesto');
const contact=reactive({name:'',email:'',phone:'',company:''});
const personalization=reactive<Personalization>({enabled:false,technique:'asesoramiento',placement:'',notes:''});
const notes=ref('');const desiredDate=ref('');const privacy=ref(false);const website=ref('');
async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;error.value='';if(file.size>3*1024*1024){error.value='El logo debe pesar menos de 3 MB.';return;}uploadBusy.value=true;try{const body=new FormData();body.append('logo',file);const result=await $fetch<{id:string;token:string;name:string}>('/api/uploads',{method:'POST',body});personalization.uploadId=result.id;personalization.uploadToken=result.token;uploadedName.value=result.name;}catch(e){error.value=errorMessage(e);}finally{uploadBusy.value=false;}}
function removeUpload(){delete personalization.uploadId;delete personalization.uploadToken;uploadedName.value='';}
watch(()=>personalization.enabled,enabled=>{if(!enabled)removeUpload();});
async function submit(){if(busy.value || uploadBusy.value)return;fields.value={};error.value='';const parsed=requestSchema.safeParse({type:type.value,contact,lines:selection.lines.map(({reference,color,size,quantity})=>({reference,color,size,quantity})),personalization:{...personalization},notes:notes.value,...(desiredDate.value?{desiredDate:desiredDate.value}:{}),privacy:privacy.value,website:website.value});if(!parsed.success){for(const issue of parsed.error.issues)fields.value[issue.path.join('.')]=issue.message;error.value='Revisa los campos indicados antes de enviar.';await nextTick();document.querySelector<HTMLElement>('.checkout-form [aria-invalid=true]')?.focus();document.querySelector('.checkout-form')?.scrollIntoView({behavior:'smooth'});return;}busy.value=true;
try{const payload=JSON.stringify(parsed.data);let key: string=crypto.randomUUID();try{const previous=JSON.parse(sessionStorage.getItem('ellas-last-submission') || 'null') as {payload:string;key:string}|null;if(previous?.payload===payload)key=previous.key;else sessionStorage.setItem('ellas-last-submission',JSON.stringify({payload,key}));}catch{/* In-memory protection still prevents double clicks. */}const result=await $fetch<{number:string}>('/api/requests',{method:'POST',body:parsed.data,headers:{'idempotency-key':key},timeout:30000});selection.clear();selection.drafts={};await navigateTo({path:'/confirmacion',query:{numero:result.number,tipo:type.value}});}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
</script>
<template><div class="container selection-page"><ClientOnly><div v-if="selection.lines.length" class="checkout-layout"><div><OrderGroups /><form class="checkout-form" novalidate @submit.prevent="submit"><section class="form-section"><h2><span class="step-circle">1</span> ¿Le ponemos tu logo?</h2><label class="checkbox-row"><input v-model="personalization.enabled" type="checkbox" /><span>Quiero personalizar mis prendas <small>El equipo revisará el logo, la técnica y su ubicación.</small></span></label><div v-if="personalization.enabled" class="personalization-fields"><div class="form-grid"><label>Técnica preferida<select v-model="personalization.technique"><option value="asesoramiento">Necesito asesoramiento</option><option value="bordado">Bordado</option><option value="serigrafia">Serigrafía</option><option value="dtf">DTF</option><option value="transfer">Transfer</option></select></label><label>Ubicación del logo<input v-model="personalization.placement" placeholder="Ej. pecho izquierdo, espalda…" maxlength="200" /></label></div><label class="upload-zone"><AppIcon name="Upload" :size="26" /><strong>{{uploadBusy?'Cargando tu imagen…':uploadedName || 'Añade el logo de tu equipo'}}</strong><span>PNG, JPG o WebP · Hasta 3 MB</span><input type="file" accept="image/png,image/jpeg,image/webp" :disabled="uploadBusy" @change="upload" /></label><button v-if="uploadedName" type="button" class="text-link" @click="removeUpload">Quitar logo <AppIcon name="X" :size="15" /></button><label>Detalles de personalización<textarea v-model="personalization.notes" rows="2" maxlength="2000" placeholder="Ej. logo en polos y camisetas; sudaderas sin personalizar." /></label></div></section>
<section class="form-section"><h2><span class="step-circle">2</span> ¿Cómo seguimos?</h2><div class="request-type"><label :class="{selected:type==='presupuesto'}"><input v-model="type" type="radio" value="presupuesto" /><div><strong>Solicitar presupuesto</strong><span>Quiero una propuesta económica.</span></div><AppIcon name="FileText" /></label><label :class="{selected:type==='pedido'}"><input v-model="type" type="radio" value="pedido" /><div><strong>Solicitar pedido</strong><span>Pendiente de confirmación del equipo.</span></div><AppIcon name="ShoppingBag" /></label></div></section>
<section class="form-section"><h2><span class="step-circle">3</span> Los datos para contactar contigo</h2><div class="form-grid"><label>Nombre y apellidos <span class="required">*</span><input v-model="contact.name" autocomplete="name" maxlength="100" :aria-invalid="!!fields['contact.name']" /><span v-if="fields['contact.name']" class="field-error">{{fields['contact.name']}}</span></label><label>Empresa <span class="optional">opcional</span><input v-model="contact.company" autocomplete="organization" maxlength="150" /></label><label>Email <span class="required">*</span><input v-model="contact.email" type="email" autocomplete="email" maxlength="254" :aria-invalid="!!fields['contact.email']" /><span v-if="fields['contact.email']" class="field-error">{{fields['contact.email']}}</span></label><label>Teléfono <span class="required">*</span><input v-model="contact.phone" type="tel" autocomplete="tel" maxlength="30" :aria-invalid="!!fields['contact.phone']" /><span v-if="fields['contact.phone']" class="field-error">{{fields['contact.phone']}}</span></label><label>Fecha deseada <span class="optional">opcional</span><input v-model="desiredDate" type="date" :min="new Date().toISOString().slice(0,10)" /><small>Sujeta a confirmación de disponibilidad y plazos.</small></label></div><label>Algo más que debamos saber <span class="optional">opcional</span><textarea v-model="notes" rows="3" maxlength="3000" placeholder="Cuéntanos lo que necesita tu equipo…" /></label><label class="honeypot" aria-hidden="true">Web<input v-model="website" tabindex="-1" autocomplete="off" /></label><label class="checkbox-row privacy-checkbox"><input v-model="privacy" type="checkbox" :aria-invalid="!!fields.privacy" /><span>He leído la <NuxtLink to="/privacidad" target="_blank">información de privacidad</NuxtLink> y acepto el tratamiento de mis datos para gestionar esta solicitud.</span></label><p v-if="fields.privacy" class="field-error">{{fields.privacy}}</p><div v-if="error" class="alert error" role="alert">{{error}}</div><button type="submit" class="button dark full submit-request" :disabled="busy || uploadBusy">{{busy?'Guardando tu solicitud…':type==='presupuesto'?'Solicitar presupuesto':'Solicitar pedido'}}<AppIcon name="ArrowUpRight" /></button><p class="fine-print centered">Tu solicitud se guarda antes de enviar el aviso por email. No realizas ningún pago.</p></section></form></div><aside class="checkout-summary"><span class="eyebrow">LO TENEMOS TODO A PUNTO</span><h2>Tu equipo,<br /><span class="serif-word">en marcha.</span></h2><div><span>Variantes seleccionadas</span><b>{{selection.lines.length}}</b></div><div><span>Total de prendas</span><b>{{selection.count}}</b></div><div><span>Personalización</span><b>{{personalization.enabled?'Sí':'No'}}</b></div><p class="summary-price">Precio bajo presupuesto</p><p>Confirmaremos precio, existencias y plazos antes de formalizar el pedido.</p><ul><li><AppIcon name="Check" :size="17" /> Sin registro obligatorio</li><li><AppIcon name="Check" :size="17" /> Sin pago online</li><li><AppIcon name="Check" :size="17" /> Atención del equipo de la tienda</li></ul><a href="tel:917261728" class="text-link"><AppIcon name="Phone" :size="17" /> 91 726 17 28</a></aside></div><div v-else class="empty-state selection-empty"><AppIcon name="ShoppingBag" :size="48" /><h2>Tu equipo empieza aquí</h2><p>Añade tus primeras prendas y combina tallas y colores.</p><NuxtLink to="/catalogo" class="button dark">Explorar el catálogo <AppIcon name="ArrowUpRight" /></NuxtLink></div><template #fallback><div class="empty-state"><p>Cargando tu pedido…</p></div></template></ClientOnly></div></template>
